                has_ske = True
            if hs_type == 0x0b:
                has_cert = True
            pos += 4 + hs_len
        offset += 5 + rec_len
    if has_ske:
        print(f'{fname}: SKE={has_ske}, CERT={has_cert}, size={len(data)}')
